const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const categories=['All','Repair','Refine','Reset','Activate','Restructure','Optimize','Amplify','Protect','Renew','Calm','Base'];
let products=[];
const dialog=$('#product-dialog'), searchDialog=$('#search-dialog');
function openDialog(d){d.showModal();document.body.classList.add('locked')}
$$('dialog').forEach(d=>{d.addEventListener('close',()=>document.body.classList.remove('locked'));d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
$$('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
$('#menu-toggle')?.addEventListener('click',()=>{const b=$('#menu-toggle'),m=$('#mobile-menu'),on=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',String(on));b.setAttribute('aria-label',on?'Close navigation':'Open navigation');m.style.top=$('.site-header').getBoundingClientRect().bottom+'px';m.classList.toggle('open',on)});
addEventListener('scroll',()=>{const m=$('#mobile-menu');if(m?.classList.contains('open'))m.style.top=$('.site-header').getBoundingClientRect().bottom+'px'},{passive:true});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#mobile-menu')?.classList.remove('open');$('#menu-toggle')?.setAttribute('aria-expanded','false')}});
$$('[data-search]').forEach(b=>b.addEventListener('click',()=>{openDialog(searchDialog);$('#global-search').focus()}));
function productType(p){return /capsule/i.test(p.name)?'Capsules':/water/i.test(p.name)?'Research water':/kit/i.test(p.name)?'Research accessory':/blend|\//i.test(p.name)?'Research blend':'Research material'}
function card(p){return `<article class="product-card"><a class="product-art" href="product.html?item=${encodeURIComponent(p.slug)}" aria-label="View ${safe(p.name)}"><span class="product-label">${safe(p.categories[0]||'The collection')}</span><img src="${p.image}" width="900" height="900" loading="lazy" alt="BKG ${safe(p.name)} bottle"></a><button class="quick-view" data-product="${safe(p.slug)}" aria-label="Quick view ${safe(p.name)}">+</button><div class="product-meta"><div><h3><a href="product.html?item=${encodeURIComponent(p.slug)}">${safe(p.name)}</a></h3><div class="product-type">${productType(p)}</div></div><span class="price">${money(p.price)}</span></div></article>`}
function bindQuick(){ $$('[data-product]').forEach(b=>{b.onclick=()=>showProduct(products.find(p=>p.slug===b.dataset.product))})}
function productDetail(p){return `<div class="quick-layout"><div class="quick-image"><img src="${p.image}" alt="${safe(p.name)} — original BKG packaging"></div><div class="quick-content"><span class="eyebrow">BKG PERFORMANCE LAB / ${safe(p.categories[0]||'COLLECTION')}</span><${$('#product-page')?'h1':'h2'}>${safe(p.name)}</${$('#product-page')?'h1':'h2'}><p class="quick-price">${money(p.price)} <small style="font-size:10px">USD</small></p><p>${productType(p)} from the BKG collection. Explore the current product listing for complete product information, availability, and ordering.</p>${p.details?.length?`<dl class="product-specs">${p.details.map(d=>{const [k,...v]=d.split(':');return `<div><dt>${safe(k)}</dt><dd>${safe(v.join(':').trim())}</dd></div>`}).join('')}</dl>`:''}<p style="margin-top:18px">For laboratory research use only. Not for human or animal use.</p><a class="btn" href="${p.url}" target="_blank" rel="noopener">View product at BKG <span class="arrow">↗</span></a><p class="fine">Opens BKG’s existing store. Current price and availability are confirmed there.</p></div></div>`}
function showProduct(p){if(!p)return;$('#product-dialog-content').innerHTML=productDetail(p);openDialog(dialog)}
function searchResults(){const q=$('#global-search').value.toLowerCase().trim();const matches=products.filter(p=>p.name.toLowerCase().includes(q)).slice(0,7);$('#search-results').innerHTML=matches.length?matches.map(p=>`<a class="search-result" href="product.html?item=${p.slug}"><img src="${p.image}" alt=""><div>${safe(p.name)}</div><span>${money(p.price)} ↗</span></a>`).join(''):'<p>No matching materials. Try a different product name.</p>'}
$('#global-search')?.addEventListener('input',searchResults);
function renderCatalog(){const grid=$('#catalog-grid');if(!grid)return;const q=$('#catalog-search').value.trim().toLowerCase(),cat=$('#categories .active')?.dataset.category||'All',sort=$('#sort').value;let list=products.filter(p=>(cat==='All'||p.categories.includes(cat))&&p.name.toLowerCase().includes(q));if(sort==='price-low')list.sort((a,b)=>a.price-b.price);if(sort==='price-high')list.sort((a,b)=>b.price-a.price);if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));grid.innerHTML=list.length?list.map(card).join(''):'<div class="empty"><h3>No materials found.</h3><p>Try a different name or explore another category.</p><button class="btn outline" id="reset-filters">Clear filters <span>↗</span></button></div>';$('#result-count').textContent=`${list.length} ${list.length===1?'material':'materials'}${cat!=='All'?' · '+cat:''}`;$('#reset-filters')?.addEventListener('click',()=>{$('#catalog-search').value='';$$('#categories button').forEach(b=>{b.classList.toggle('active',b.dataset.category==='All');b.setAttribute('aria-pressed',String(b.dataset.category==='All'))});renderCatalog()});bindQuick()}
async function initProducts(){try{const res=await fetch('products.json');if(!res.ok)throw Error('Catalog unavailable');products=await res.json();if($('#featured-grid')){const slugs=['bpc-157-10mg','ghk-cu-50mg','mots-c-10mg','nad-500mg'];let picks=slugs.map(s=>products.find(p=>p.slug===s)).filter(Boolean);if(picks.length<4)picks=[products.find(p=>p.name==='BPC-157 10mg'),products.find(p=>p.name==='GHK-Cu 100mg'),products.find(p=>p.name==='MOTS-C 10mg'),products.find(p=>p.name==='NAD+ 500mg')].filter(Boolean);$('#featured-grid').innerHTML=picks.map(card).join('');bindQuick();window.ScrollTrigger&&ScrollTrigger.refresh()}if($('#categories')){const initial=new URLSearchParams(location.search).get('category')||'All';$('#categories').innerHTML='<span class="eyebrow">Shop by category</span>'+categories.map(c=>`<button data-category="${c}" class="${c===initial?'active':''}" aria-pressed="${c===initial}">${c}<span>${c==='All'?products.length:products.filter(p=>p.categories.includes(c)).length}</span></button>`).join('');if(!$('#categories .active'))$('#categories button').classList.add('active');$$('#categories button').forEach(b=>b.addEventListener('click',()=>{$$('#categories button').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});const u=new URL(location);if(b.dataset.category==='All')u.searchParams.delete('category');else u.searchParams.set('category',b.dataset.category);history.replaceState(null,'',u);renderCatalog()}));$('#catalog-search').addEventListener('input',renderCatalog);$('#sort').addEventListener('change',renderCatalog);renderCatalog()}if($('#product-page')){const slug=new URLSearchParams(location.search).get('item');const p=products.find(p=>p.slug===slug);$('#product-page').innerHTML=p?productDetail(p):'<div class="empty"><h1 style="font-size:50px">Material not found.</h1><a class="btn" href="shop.html">Explore the collection ↗</a></div>';if(p){document.title=`${p.name} | BKG Performance Lab`;$('#product-breadcrumb').textContent=p.name}}searchResults()}catch(e){$$('#catalog-grid,#featured-grid,#product-page').forEach(el=>el.innerHTML='<p>The collection could not load. <a href="https://www.bkgperformancepartners.com">Visit the BKG store ↗</a></p>')}}
initProducts();
function prepareEmail(form,type){form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const d=new FormData(form),lines=[];for(const [key,val] of d.entries())lines.push(`${key}: ${val}`);const subject=type==='affiliate'?'BKG Affiliate Application':`BKG Inquiry — ${d.get('Subject')||'The Lab'}`;const body=lines.join('\r\n\r\n');const url=`mailto:Sales@BKGPerformance.com?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;const status=$('.application-status',form);status.innerHTML=`<strong>Your ${type==='affiliate'?'application':'message'} is ready to review.</strong><p style="margin:8px 0">Nothing has been sent. Open the draft in your email app, or download it and email it to Sales@BKGPerformance.com.</p><div class="actions"><a class="btn" href="${safe(url)}">Open email draft <span>↗</span></a><button type="button" class="text-link" data-download-draft>Download text <span>↓</span></button></div>`;$('[data-download-draft]',status).onclick=()=>{const blob=new Blob([`To: Sales@BKGPerformance.com\r\nSubject: ${subject}\r\n\r\n${body}`],{type:'text/plain;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=type==='affiliate'?'BKG-Affiliate-Application.txt':'BKG-Inquiry.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};status.scrollIntoView({behavior:reduced.matches?'instant':'smooth',block:'nearest'})})}
if($('#affiliate-form'))prepareEmail($('#affiliate-form'),'affiliate');if($('#contact-form'))prepareEmail($('#contact-form'),'contact');
const videoObservers=new IntersectionObserver(entries=>entries.forEach(({target:v,isIntersecting})=>{if(isIntersecting&&!reduced.matches&&!v.dataset.paused)v.play().catch(()=>{});else v.pause()}),{threshold:.1});
$$('video').forEach(v=>{if(reduced.matches){v.pause();v.removeAttribute('autoplay')}else{if(v.dataset.src){v.src=v.dataset.src;v.load()}videoObservers.observe(v)}});
$$('[data-pause-video]').forEach(b=>b.addEventListener('click',()=>{const v=$(b.dataset.pauseVideo);if(v.paused){v.dataset.paused='';v.play().catch(()=>{});b.textContent='Pause film';b.setAttribute('aria-pressed','false')}else{v.dataset.paused='true';v.pause();b.textContent='Play film';b.setAttribute('aria-pressed','true')}}));
const story=$('#assembly');let storyTrigger;
function storyStep(i){$$('.assembly-step').forEach((s,j)=>{s.classList.toggle('active',i===j);s.classList.toggle('done',j<i);$('button',s).setAttribute('aria-current',String(i===j))})}
$$('[data-assembly-step]').forEach(b=>b.addEventListener('click',()=>{const n=Number(b.dataset.assemblyStep);storyStep(n);if(storyTrigger&&!reduced.matches)window.scrollTo({top:storyTrigger.start+(storyTrigger.end-storyTrigger.start)*((n+.5)/4),behavior:'smooth'})}));
const walk=$('#lab-walk'),walkFrames=240,walkImgs=[];let labTrigger,walkChapter=-1,walkCur=0,walkTarget=0,walkPrev=0,walkLoop=0;
// scroll progress -> video frame; each segment eases in and out so the camera pushes, then settles
const walkKeys=[[0,0],[.12,46],[.3,124],[.5,146],[.72,222],[.88,239],[1,239]];
// where each chapter card is on screen, in scroll progress; between them the video plays clean
const walkShow=[[0,.15],[.33,.55],[.8,1.01]];
const walkEase=t=>t<.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2;
function walkMap(p){for(let i=1;i<walkKeys.length;i++){const[a,fa]=walkKeys[i-1],[b,fb]=walkKeys[i];if(p<=b)return fa+(fb-fa)*walkEase((p-a)/(b-a||1))}return walkFrames-1}
function walkLoad(){if(walkImgs[0])return;walkImgs.length=walkFrames;const order=[];for(const step of[16,4,1])for(let i=0;i<walkFrames;i+=step)if(!order.includes(i))order.push(i);for(const i of order){const im=new Image();im.decoding='async';im.onload=()=>{if(Math.abs(i-Math.round(walkCur))<4)walkDraw()};im.src=`assets/lab-walk/f${String(i+1).padStart(3,'0')}.webp`;walkImgs[i]=im}}
const walkReady=im=>im&&im.complete&&im.naturalWidth;
function walkFrame(i){i=Math.max(0,Math.min(walkFrames-1,i));for(let d=0;d<walkFrames;d++)for(const k of[i-d,i+d]){const im=walkImgs[k];if(walkReady(im))return im}return null}
function walkDraw(){const c=$('#walk-canvas');if(!c)return;const r=c.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2),w=Math.round(r.width*dpr),h=Math.round(r.height*dpr);if(!w||!h)return;if(c.width!==w||c.height!==h){c.width=w;c.height=h}if(!walkFrame(Math.round(walkCur)))return;const s=Math.max(w/1280,h/720),dw=1280*s,dh=720*s,ox=(w-dw)/2,oy=(h-dh)/2,g=c.getContext('2d');
// motion blur: the faster the camera moves, the more trailing frames are layered in
const v=Math.min(6,Math.abs(walkCur-walkPrev)),n=v>.4?Math.min(5,1+Math.round(v)):1;g.globalAlpha=1;for(let k=0;k<n;k++){const f=walkCur-(walkCur>walkPrev?1:-1)*v*(k/n),f0=Math.floor(f),fr=f-f0,a=walkFrame(f0),b=walkImgs[Math.min(walkFrames-1,f0+1)];g.globalAlpha=1/(k+1);g.drawImage(a,ox,oy,dw,dh);if(fr>.01&&walkReady(b)){g.globalAlpha=fr/(k+1);g.drawImage(b,ox,oy,dw,dh)}}g.globalAlpha=1}
function walkTick(){walkPrev=walkCur;walkCur+=(walkTarget-walkCur)*.085;if(Math.abs(walkTarget-walkCur)<.01)walkCur=walkTarget;walkDraw();walkLoop=walkCur!==walkTarget||walkPrev!==walkCur?requestAnimationFrame(walkTick):0}
function walkTo(f){walkTarget=f;if(!walkLoop)walkLoop=requestAnimationFrame(walkTick)}
function setWalk(i,show){walkChapter=i;$$('.walk-chapter').forEach((c,j)=>c.classList.toggle('active',show&&j===i));$$('[data-walk-step]').forEach((b,j)=>{b.classList.toggle('active',j===i);b.classList.toggle('done',j<i);b.setAttribute('aria-current',String(j===i))})}
function walkUpdate(p){walkTo(walkMap(p));let i=0,show=false;walkShow.forEach(([a,b],j)=>{if(p>=a)i=j;if(p>=a&&p<b)show=true});setWalk(i,show);walk.style.setProperty('--reveal',Math.min(1,p/.06).toFixed(3));$$('[data-walk-step]').forEach((b,j)=>b.style.setProperty('--fill',Math.min(1,Math.max(0,(p-j/3)*3)).toFixed(3)))}
$$('[data-walk-step]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.walkStep),[a,e]=walkShow[i];if(labTrigger&&!reduced.matches)scrollTo({top:labTrigger.start+(labTrigger.end-labTrigger.start)*Math.min(.99,(a+e)/2),behavior:'smooth'})}));
if(walk){setWalk(0,true);if(matchMedia('(prefers-reduced-motion: reduce)').matches)walkCur=walkTarget=146;new IntersectionObserver((e,o)=>{if(e[0].isIntersecting){walkLoad();o.disconnect()}},{rootMargin:'150% 0px'}).observe(walk);addEventListener('resize',walkDraw)}
if(window.gsap&&window.ScrollTrigger){gsap.registerPlugin(ScrollTrigger);const mm=gsap.matchMedia();mm.add('(prefers-reduced-motion: no-preference)',()=>{document.body.classList.add('js-motion');$$('.reveal').forEach(el=>gsap.to(el,{opacity:1,y:0,duration:.8,ease:'power2.out',scrollTrigger:{trigger:el,start:'top 91%',once:true}}));if($('.hero')){gsap.to('.bottle-main',{y:45,ease:'none',scrollTrigger:{trigger:'.hero',start:'top top',end:'bottom top',scrub:1}});gsap.to('.bottle-left',{y:-30,ease:'none',scrollTrigger:{trigger:'.hero',start:'top top',end:'bottom top',scrub:1}});gsap.to('.bottle-right',{y:70,ease:'none',scrollTrigger:{trigger:'.hero',start:'top top',end:'bottom top',scrub:1}})}if(story){gsap.set('.vpart.stopper',{yPercent:-10});gsap.set('.vpart.crimp',{yPercent:-20});gsap.set('.vpart.flip',{yPercent:-30});gsap.set('.assembly-stack',{yPercent:12});const tl=gsap.timeline({defaults:{ease:'power2.inOut'},scrollTrigger:{trigger:story,start:()=>`top ${innerWidth<801?73:87}px`,end:'bottom bottom',scrub:.6,onUpdate:s=>{storyStep(Math.min(3,Math.floor(s.progress*4)));$('.progress-fill',story).style.width=(s.progress*100)+'%'}}});storyTrigger=tl.scrollTrigger;tl.to('.vpart.stopper',{yPercent:0,duration:.12},.16).to('.vpart.crimp',{yPercent:0,duration:.12},.41).to('.vpart.flip',{yPercent:0,duration:.12},.66).to('.assembly-stack',{yPercent:0,scale:1.05,duration:.62,ease:'none'},.16).to('.callout',{opacity:1,duration:.06,stagger:.02,ease:'none'},.8).to({},{duration:.06},.94)}if(walk){labTrigger=ScrollTrigger.create({trigger:walk,start:()=>`top ${innerWidth<801?73:87}px`,end:'bottom bottom',onUpdate:s=>walkUpdate(s.progress)})}return()=>{document.body.classList.remove('js-motion');storyTrigger=null;labTrigger=null}})}
reduced.addEventListener('change',()=>{$$('video').forEach(v=>{if(reduced.matches)v.pause();else if(!v.dataset.paused){if(!v.src&&v.dataset.src)v.src=v.dataset.src;v.play().catch(()=>{})}})});
